typedef unsigned int nslSoundId;
enum { MENUSOUND_MAXSOURCES = 32, NSL_SOUNDSTATUS_INVALID = 0 };

class MenuEntry {
public:
    int data;
    virtual ~MenuEntry();
};
class MenuEntryFunction : public MenuEntry {};
class SoundMenuEntryFunctionFloatEdit : public MenuEntry {
    char padding[52];
public:
    unsigned int src;
    nslSoundId snd;
};
class Menu {
    int padding;
    int entries;
public:
    int NumEntries();
    void ClearMenu();
    void OnClose(bool);
};
class MenuSoundDraw : public Menu {
public:
    void OnClose(bool);
};

extern SoundMenuEntryFunctionFloatEdit *MENUSOUND_SourceEntries[MENUSOUND_MAXSOURCES];
extern MenuEntryFunction *DumpFunc;
extern int nslGetSoundStatus(nslSoundId);
extern void nslStopSound(nslSoundId);
extern void nslUnpauseAllSounds();
extern void mem_lock_malloc(bool);
__asm__(".equ MENUSOUND_SourceEntries,0x00579950");
__asm__(".equ DumpFunc,0x005799D0");
__asm__(".equ nslGetSoundStatus__FUi,0x0038DBA0");
__asm__(".equ nslStopSound__FUi,0x0038D288");
__asm__(".equ nslUnpauseAllSounds__Fv,0x0038D8D8");
__asm__(".equ mem_lock_malloc__Fb,0x002AC438");
__asm__(".equ NumEntries__4Menu,0x0023E4D8");
__asm__(".equ ClearMenu__4Menu,0x0023E538");
__asm__(".equ OnClose__4Menub,0x0023EB70");

void MenuSoundDraw::OnClose(bool toparent)
{
    int i;
    for (i=0; i < MENUSOUND_MAXSOURCES; i++)
    {
        if (nslGetSoundStatus(MENUSOUND_SourceEntries[i]->snd) != NSL_SOUNDSTATUS_INVALID)
        {
            nslStopSound(MENUSOUND_SourceEntries[i]->snd);
        }
    }

    nslUnpauseAllSounds();
    mem_lock_malloc(false);

    for (i=0; i < NumEntries()-1; i++)
    {
        delete MENUSOUND_SourceEntries[i];
        MENUSOUND_SourceEntries[i] = 0;
    }
    delete DumpFunc;
    DumpFunc = 0;
    ClearMenu();

    mem_lock_malloc(true);
    Menu::OnClose(toparent);
}
